// Generates src/lib/generated/icon-bundle.ts with the icon data for every
// solar:/mdi: icon referenced in src/. Bundling the data means the app never
// calls api.iconify.design at runtime — icons render offline, on first visit,
// and on networks that block third-party CDNs, which matches Dustic's
// no-tracking / offline-PWA goals.
import { readFileSync, writeFileSync, mkdirSync, readdirSync, statSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join, extname } from 'path';
import { createRequire } from 'module';
import { getIcons } from '@iconify/utils';

const require = createRequire(import.meta.url);
const __dirname = dirname(fileURLToPath(import.meta.url));
const srcDir = join(__dirname, '../src');

const COLLECTIONS = {
	solar: require('@iconify-json/solar/icons.json'),
	mdi: require('@iconify-json/mdi/icons.json')
};

// Collect every "<prefix>:<icon-name>" string literal in source files.
const ICON_RE = /\b(solar|mdi):([a-z0-9][a-z0-9-]*)/g;
const used = { solar: new Set(), mdi: new Set() };

function walk(dir) {
	for (const entry of readdirSync(dir)) {
		const full = join(dir, entry);
		if (statSync(full).isDirectory()) {
			if (entry === 'generated') continue;
			walk(full);
		} else if (['.svelte', '.ts', '.js'].includes(extname(full))) {
			const text = readFileSync(full, 'utf8');
			for (const m of text.matchAll(ICON_RE)) {
				used[m[1]].add(m[2]);
			}
		}
	}
}
walk(srcDir);

let totalIcons = 0;
const chunks = [];
const missing = [];
for (const [prefix, collection] of Object.entries(COLLECTIONS)) {
	const names = [...used[prefix]].sort();
	if (names.length === 0) continue;
	const subset = getIcons(collection, names, true);
	if (subset?.not_found?.length) {
		missing.push(...subset.not_found.map((n) => `${prefix}:${n}`));
		delete subset.not_found;
	}
	totalIcons += Object.keys(subset.icons).length;
	chunks.push(`addCollection(${JSON.stringify(subset)});`);
}

if (missing.length) {
	console.error(`Icon names referenced in src/ but missing from their collection: ${missing.join(', ')}`);
	process.exit(1);
}

const outDir = join(srcDir, 'lib/generated');
mkdirSync(outDir, { recursive: true });
const content = `// Auto-generated by scripts/generate-icon-bundle.js - DO NOT EDIT MANUALLY
// Registers icon data for every icon used in the app so nothing is
// fetched from api.iconify.design at runtime.
import { addCollection } from '@iconify/svelte';

${chunks.join('\n\n')}
`;
writeFileSync(join(outDir, 'icon-bundle.ts'), content);
console.log(`Generated icon bundle: ${totalIcons} icons (${[...used.solar].length} solar, ${[...used.mdi].length} mdi)`);
